// Foreground, opt-in location reminder; food-app events remain an explicit demo.
(()=>{
const coreRender=render,coreGo=go;let demoTimer=null;
const reminderText='Thinking of eating soon? Check your personal meal and insulin plan, including timing.';
function icon(){try{const c=document.createElement('canvas');c.width=480;c.height=310;paintWorld(c,state.equipped.Rooms||'cozy',state.equipped,'range','Reading',true,false,Date.now());return c.toDataURL('image/png')}catch{return ''}}
function notify(source){const title=buddyName()+' has a gentle reminder';const overlay=document.createElement('section');overlay.className='reminder-popup';overlay.setAttribute('role','status');overlay.innerHTML=`<canvas width="480" height="310" aria-label="Your customized companion"></canvas><div><small>${escapeHTML(source)}</small><strong>${escapeHTML(title)}</strong><p>${escapeHTML(reminderText)}</p><button type="button">Got it</button></div>`;document.body.appendChild(overlay);try{paintWorld(overlay.querySelector('canvas'),state.equipped.Rooms||'cozy',state.equipped,'range','Reading',true,false,Date.now())}catch{}overlay.querySelector('button').onclick=()=>overlay.remove();setTimeout(()=>overlay.remove(),18000);if(window.Notification&&Notification.permission==='granted'){try{new Notification(title,{body:reminderText,icon:icon(),tag:'diabuddy-meal-reminder'})}catch{}}}
function status(t){const el=$('#reminder-status');if(el)el.textContent=t}
function reminderPage(){content.innerHTML=greeting('A little reminder, from a friend.','Your companion can help you remember to check your personal plan.','MEAL REMINDERS')+`<section class="card card-pad"><h2>Try the demo</h2><p>Show a character notification without visiting a restaurant or opening another app.</p><div class="reminder-actions"><button class="primary" id="demo-place">Simulate a visit · 5 seconds</button><button class="secondary" id="demo-food-app">Simulate opening a food app</button><button class="secondary" id="demo-cancel">Cancel demo</button></div><p class="helper" id="demo-status" role="status">Demo events are simulated and don’t monitor your device.</p></section><section class="card card-pad" style="margin-top:18px"><h2>System notifications</h2><p>For the demo, optionally allow system notifications. In-app character notifications work without this permission.</p><button class="secondary" id="enable-notifications">Allow system notifications</button><p class="helper" id="reminder-status" role="status">No system notification permission requested.</p><p class="helper">Restaurant visits and food-app openings are simulated. This web app does not monitor your location or other apps.</p><p class="notice">Reminders are optional and do not determine whether to bolus or when to eat. Follow your personal care plan. Never delay treatment for low glucose.</p></section>`;
$('#demo-place').onclick=()=>{clearTimeout(demoTimer);$('#demo-status').textContent='SIMULATED: At a food establishment. Reminder in 5 seconds (represents 1–2 minutes).';demoTimer=setTimeout(()=>{notify('SIMULATED · RESTAURANT VISIT');const e=$('#demo-status');if(e)e.textContent='Simulated visit complete.'},5000)};$('#demo-food-app').onclick=()=>notify('SIMULATED · FOOD APP OPENED');$('#demo-cancel').onclick=()=>{clearTimeout(demoTimer);$('#demo-status').textContent='Demo cancelled.'};$('#enable-notifications').onclick=async()=>{if(!window.Notification){status('System notifications are not available in this browser. In-app reminders still work.');return}try{const permission=await Notification.requestPermission();status(permission==='granted'?'System notification permission granted.':'System notifications are not enabled. In-app reminders still work.')}catch{status('System notifications unavailable here. In-app reminders still work.')}};}
render=function(){coreRender();if(page==='reminders')reminderPage()};go=function(p){coreGo(p);if(p==='reminders')$('#page-label').textContent='MEAL REMINDERS'};

})();
